#!/usr/bin/env bash
# .claude/hooks/auto-index.sh
#
# Triggered by PostToolUse on Write|Edit|MultiEdit.
# When a file inside an Area is created or modified, regenerate that Area's
# _index.md to reflect the current folder contents.
#
# This is a SIMPLE structural index — folder-by-folder file listing.
# Claude or you can manually overwrite _index.md with a richer MOC at any time;
# this hook only runs if the file is missing OR contains the auto-generated marker.
#
# To disable: rename this file or remove its entry from .claude/settings.json

set -e

cd "$CLAUDE_PROJECT_DIR" || exit 0

# Bail out if disabled by sentinel (e.g. during bulk imports)
if [ -f ".claude/IMPORT_IN_PROGRESS" ]; then
  cat >/dev/null
  exit 0
fi

# Read JSON payload from stdin to find the file that was changed
PAYLOAD=$(cat)

# Try jq first (most reliable); fall back to portable sed if jq isn't available.
# Avoid grep -P here — git-bash on Windows often errors with
# "grep -P supports only unibyte and UTF-8 locales".
if command -v jq >/dev/null 2>&1; then
  CHANGED_FILE=$(echo "$PAYLOAD" | jq -r '.tool_input.file_path // empty')
else
  CHANGED_FILE=$(echo "$PAYLOAD" | sed -n 's/.*"file_path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -1)
fi

# Bail if we couldn't extract a file path
if [ -z "$CHANGED_FILE" ]; then
  exit 0
fi

# Normalize Windows backslashes to forward slashes so path matching works
CHANGED_FILE="${CHANGED_FILE//\\/\/}"

# Only act on files inside 1-Areas/
case "$CHANGED_FILE" in
  *1-Areas/*) ;;
  *) exit 0 ;;
esac

# Extract the Area path: everything up through the first folder under 1-Areas/
AREA_PATH=$(echo "$CHANGED_FILE" | sed -E 's|(.*1-Areas/[^/]+).*|\1|')

# Sanity check
if [ ! -d "$AREA_PATH" ]; then
  exit 0
fi

INDEX_FILE="$AREA_PATH/_index.md"
AUTO_MARKER="<!-- AUTO-INDEX: regenerated by hook -->"

# Don't overwrite a hand-curated index — only regenerate if missing or marked auto
if [ -f "$INDEX_FILE" ]; then
  if ! grep -q "$AUTO_MARKER" "$INDEX_FILE"; then
    # Check if it's a placeholder (small file with "will be populated" text)
    SIZE=$(wc -c < "$INDEX_FILE" | tr -d ' ')
    if [ "$SIZE" -gt 200 ] && ! grep -q "will be populated" "$INDEX_FILE"; then
      # Hand-curated content present — leave it alone
      exit 0
    fi
  fi
fi

AREA_NAME=$(basename "$AREA_PATH")

# Extract a one-line summary from a markdown file.
# Strategy: skip YAML frontmatter, skip H1 title and other headings, find the first
# non-empty content line, strip common markdown noise, truncate to 120 chars.
# Returns empty string if no summary line is available.
extract_summary() {
  local file="$1"
  awk '
    BEGIN { in_fm = 0 }
    NR == 1 && /^---[[:space:]]*$/ { in_fm = 1; next }
    in_fm && /^---[[:space:]]*$/ { in_fm = 0; next }
    in_fm { next }
    /^[[:space:]]*$/ { next }
    /^#+[[:space:]]/ { next }
    /^<!--/ { next }
    {
      line = $0
      gsub(/\[\[/, "", line); gsub(/\]\]/, "", line)
      gsub(/\*\*/, "", line); gsub(/__/, "", line)
      gsub(/`/, "", line)
      # Convert [text](url) to text (basic, single-line)
      while (match(line, /\[[^]]+\]\([^)]+\)/)) {
        before = substr(line, 1, RSTART - 1)
        match_str = substr(line, RSTART, RLENGTH)
        # Extract the [text] portion
        text_match = match_str
        sub(/\]\(.*$/, "", text_match)
        sub(/^\[/, "", text_match)
        line = before text_match substr(line, RSTART + RLENGTH)
      }
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
      if (length(line) > 120) line = substr(line, 1, 117) "..."
      print line
      exit
    }
  ' "$file" 2>/dev/null
}

# Build a fresh structural index
{
  echo "# ${AREA_NAME} — Index"
  echo ""
  echo "$AUTO_MARKER"
  echo "<!-- To create a hand-curated index, replace the entire file contents (and remove this marker). -->"
  echo ""
  echo "*Last regenerated: $(date '+%Y-%m-%d %H:%M')*"
  echo ""

  # Walk subfolders in a sensible order
  for SUBFOLDER in projects ongoing sources archive; do
    SUB_PATH="$AREA_PATH/$SUBFOLDER"
    if [ -d "$SUB_PATH" ]; then
      # Skip if folder is empty (only .gitkeep)
      ITEM_COUNT=$(find "$SUB_PATH" -mindepth 1 -maxdepth 1 ! -name ".gitkeep" 2>/dev/null | wc -l | tr -d ' ')
      if [ "$ITEM_COUNT" -eq 0 ]; then
        continue
      fi

      echo "## ${SUBFOLDER^}"
      echo ""

      # List markdown files at the top level of this subfolder, with summary
      find "$SUB_PATH" -maxdepth 1 -type f -name "*.md" 2>/dev/null | sort | while read -r FILE; do
        FILENAME=$(basename "$FILE")
        SUMMARY=$(extract_summary "$FILE")
        if [ -n "$SUMMARY" ]; then
          echo "- [${FILENAME%.md}](./${SUBFOLDER}/${FILENAME}) — ${SUMMARY}"
        else
          echo "- [${FILENAME%.md}](./${SUBFOLDER}/${FILENAME})"
        fi
      done

      # List subdirectories (with a count of files inside)
      find "$SUB_PATH" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort | while read -r DIR; do
        DIRNAME=$(basename "$DIR")
        FILE_COUNT=$(find "$DIR" -type f -name "*.md" ! -name ".gitkeep" 2>/dev/null | wc -l | tr -d ' ')
        echo "- **${DIRNAME}/** (${FILE_COUNT} notes)"
      done

      echo ""
    fi
  done
} > "$INDEX_FILE"

exit 0
